const POINTS = 6;
var shaderCanvas, theShader;
var N = 5;
var unit = 0.25;
var coefficients;

var allPoints;
var allColors;
var allRadii;
var index;

function preload(){
	shaderCanvas = createGraphics(1112, 834, WEBGL);
	theShader = new p5.Shader(shaderCanvas.renderer, vertShader, fragShader);
	shaderCanvas.shader(theShader);
}

function setup() {	
	createCanvas(1112, 834);
	background(0);
	setupPolynomials();
}

function setupPolynomials(){
	// variables for the shader
	allPoints = [];
	allColors = [];
	allRadii = [];

	// possible coefficients
	coefficients = [];
	coefficients.push(new Complex(0,0));
	for (let k=1; k<=N; k++){
		coefficients.push(new Complex(k,0));
		coefficients.push(new Complex(-k,0));
	}

	// compute polynomials and roots
	addRootsAllPolynomials(1, [1,1,0]);
	addRootsAllPolynomials(2, [0,1,1]);
	addRootsAllPolynomials(3, [1,0,1]);
	addRootsAllPolynomials(4, [0.1,0.2,1]);	

	// tracks which points were already drawn on screen
	index = 0;
}


function addRootsAllPolynomials(degree, color){
	_addRootsAllPolynomials(degree, [], color);
}

function _addRootsAllPolynomials(degree, coef, color){
	if (degree==0){
		if (coef.length<=0) // stop with the nonsense
			return;

		// add leading coefficient
		coef.push(new Complex(1,0));
		//add roots
		var poly = new Polynomial(coef);
		addAllRootsInteger(poly, color);

		// For symmetry, take negative for coeffients at odd places to move from f(x) to f(-x)
		var opCoef = [];
		var scalar = 1;
		for (let c of coef){
			opCoef.push(c.multBy2(scalar,0));
			scalar *= -1;
		}
		addAllRootsInteger(new Polynomial(opCoef), color);

		// remove the leading coefficient
		coef.pop(); 
		return;
	}

	for (let c of coefficients){
		coef.push(c);
		_addRootsAllPolynomials(degree-1, coef, color);
		coef.pop();
	}
}

function drawShader(){
	if (allRadii.length-index<POINTS){
		return;		
	}
	theShader.setUniform("u_resolution", [shaderCanvas.width, shaderCanvas.height]);
	theShader.setUniform("u_density", shaderCanvas.pixelDensity());
	theShader.setUniform("u_time", frameCount/100);
	theShader.setUniform("u_unit", unit);

	var u_points = [];
	var u_colors = [];
	var u_radii  = [];
	for (let i=0; i<POINTS; i++){
		u_points.push(allPoints[2*index], allPoints[2*index+1]);
		u_colors.push(allColors[3*index], allColors[3*index+1], allColors[3*index+2]);
		u_radii.push(allRadii[index]);
		index++;
	}
	theShader.setUniform("u_points", u_points);
	theShader.setUniform("u_colors", u_colors);
	theShader.setUniform("u_radiuses", u_radii);

	shaderCanvas.shader(theShader);
	shaderCanvas.rect(0,0,shaderCanvas.width,shaderCanvas.height);
	image(shaderCanvas,0,0);
}

var pause = false;

function draw() {
	if (frameCount==1 || pause)
		return;
	blendMode(ADD);
	drawShader();
}

function keyPressed(){
	if (key=='p')
		pause = !pause;
}


