// === Tab: complex ===
class Complex {

	constructor(real, img){
		this.real = real;
		this.img = img;
	}

	conjugate(){
		return new Complex(this.real,-this.img);
	}

	add(z){
		if (z==null)
			return null;
		return new Complex(this.real+z.real,this.img+z.img);
	}

	add2(real, img){
		return new Complex(real+this.real,img+this.img);
	}

	sub(z){
		if (z==null)
			return null;
		return new Complex(this.real-z.real,this.img-z.img);
	}

	sub2(real, img){
		return new Complex(this.real-this.real,this.img-this.img);
	}

	multBy(z){
		if (z==null){
			return null;
		}
		return new Complex(this.real*z.real-this.img*z.img,this.real*z.img+this.img*z.real);
	}

	multBy2(real, img){
		return new Complex(this.real*real-this.img*img,this.real*img+this.img*real);
	}

	absSq(){
		return this.real*this.real+this.img*this.img;
	}

	abs(){
		return sqrt(this.real*this.real+this.img*this.img);
	}

	divide(z){
		return this.multBy(z.inverse());
	}

	inverse(){
		if (this.real==0 && this.img==0){ //zero doesn't have an inverse, so return null
			return null;
		}
		var d = this.absSq();
		return new Complex(this.real/d, -this.img/d);
	}

	toString(){
		var a = (round(this.real*1000))/1000;
		var b = (round(this.img*1000))/1000;
		return a+"+"+b+"i";
	}
}


// === Tab: polynomials ===
class Polynomial {

	constructor(coefficients){
		this.coef = coefficients;
	}

	compute(z){
		var sum = new Complex(0,0);
		var pow = new Complex(1,0);
		for (let c of this.coef){
			sum = sum.add(c.multBy(pow));
			pow = pow.multBy(z);
		}
		return sum;
	}

	derivative(){
		var derPoly = [];
		for (let i=1; i<this.coef.length; i++){
			derPoly.push(this.coef[i].multBy2(i,0));
		}
		return new Polynomial(derPoly);
	}

	findRoot(initial, error){
		var z = initial;
		var derPoly = this.derivative();

		// an approximation at z is  f(z+h)~f(z)+f'(z)h. For this to be zero, we need
		//  h = -f(z)/f'(z)
		for (let i=0; i<16; i++){
			var value = this.compute(z);
			if (value.abs()<error)
				return z;

			var derValue = derPoly.compute(z);
			if (derValue.abs()<error){
				// stuck when derivative is zero - perturbe it a little bit.
				z = z.add2(random(-0.1,0.1), random(-0.1,0.1));
				continue;
			}

			z = z.sub(value.divide(derValue));
		}
		return z;
	}

	degree(){
		// need to remove leading zeros.
		return this.coef.length-1;
	}

	// assumption: poly has leading coefficient != 0
	divide(poly){
		// copy coefficents
		var coef = [];
		for (let c of this.coef)
			coef.push(c);

		var leading = poly.coef[poly.coef.length-1];
		var deg = poly.degree();
		var divisor = [];
		for (let i=coef.length-1; i>=deg; i--){
			var scalar = coef[i].divide(leading);
			divisor.unshift(scalar);
			for (let j=0; j<=deg; j++){
				coef[i-j] = coef[i-j].sub(scalar.multBy(poly.coef[deg-j]));
			}
		}
		return new Polynomial(divisor);
	}

	toString(){
		var str = '('+this.coef[0]+')';
		for (let i=1; i<this.coef.length; i++){
			str = '('+this.coef[i]+')x^'+i+' + '+str;
		}
		return str;
	}
}


// assumption : poly's coefficients are integers.
function addAllRootsInteger(poly, color){
	if (poly.degree() >= 2){
		// if the polynomial has an integer root ignore it (decomposable).
		// should add checking if a 4 degree polynomial splits to two irreducible quadratic polynomials
		var d = abs(poly.coef[0].real);
		for (let i=-d; i<=d; i++){
			var t = abs(poly.compute(new Complex(i,0)).real);
			if (t<0.0001)
				return;
		}
	}
	var maxCoef = 0;
	for (let c of poly.coef){
		maxCoef = max(maxCoef, c.abs());
	}
	addAllRoots(poly, maxCoef, color);	
}
/**
 * 
 */
function addAllRoots(poly, polyNorm, color){
	if (poly.degree()<=0)
		return;
	var v = poly.findRoot(new Complex(Math.PI,Math.E), 0.00001);	
	var divisor = new Polynomial([v.multBy2(-1,0), new Complex(1,0)]);
	var q = poly.divide(divisor);
	addAllRoots(q, polyNorm, color);

	var size = 0.05*pow(2,-polyNorm);
	allPoints.push(v.real, v.img);
	allColors.push(color[0], color[1], color[2]);
	allRadii.push(size);
	rootCounter++;
}

function showLog(){
	return rootCounter<4*6 && 3*6<=rootCounter;
}
